const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const FILES={settings:'settings.json',projects:'projects.json',categories:'categories.json',products:'products.json',testimonials:'testimonials.json'};
const SESS='carpenter_admin', GHK='carpenter_github', ORD_KEY='carpenter_orders';
let DB={}, ORIG={}, AUTH=null, DIRTY=new Set(), PAGE='dashboard', ME=null;
/* permissions: ME comes from the sign-in server (/me). Without the server there is one owner who can do everything. */
const localME=()=>({email:AUTH&&AUTH.email,name:'',role:'super_admin',roleName:'Owner',perms:'*',owner:true});
const can=(m,a)=>!ME||ME.perms==='*'||(ME.perms||[]).includes(m+'.'+a);
const canWrite=k=>['add','edit','delete'].some(a=>can(k,a));
const canView=k=>k==='account'||can(k,'view');
function applyPerms(){const c=$('content');if(!c)return;
  c.querySelectorAll('[data-perm]').forEach(el=>{if(!el.dataset.perm.split('|').some(x=>{const[m,a]=x.split('.');return can(m,a)}))el.style.display='none'});
  if(c.dataset.ro)c.querySelectorAll('input,select,textarea,button').forEach(el=>{if(el.classList.contains('keep')||el.type==='search'||el.closest('.pager,.tools,.mback,.prevhead,.acts-cell'))return;if(el.tagName==='BUTTON')el.style.display='none';else el.disabled=true})}
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN');
const slugify=s=>String(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'item';
const nextId=a=>a.reduce((m,x)=>Math.max(m,+x.id||0),0)+1;
const byOrder=a=>a.sort((x,y)=>(x.order||999)-(y.order||999));
const renumber=a=>a.forEach((x,i)=>x.order=i+1);
function toast(m,err){const t=$('toast');t.textContent=m;t.className='show'+(err?' err':'');clearTimeout(t._t);t._t=setTimeout(()=>t.className='',err?6000:3500)}
function confirmBox(title,text,yes='Delete'){return new Promise(res=>{$('mTitle').textContent=title;$('mText').textContent=text;$('mYes').textContent=yes;$('modal').hidden=false;$('mYes').focus();const done=v=>{$('modal').hidden=true;res(v)};$('mYes').onclick=()=>done(true);$('mNo').onclick=()=>done(false);$('modal').onclick=e=>{if(e.target.id==='modal')done(false)}})}
async function sha256(s){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
const randHex=()=>[...crypto.getRandomValues(new Uint8Array(16))].map(x=>x.toString(16).padStart(2,'0')).join('');
async function fetchJSON(f){const r=await fetch('data/'+f+'?t='+Date.now());if(!r.ok)throw new Error(f);return r.json()}

const ICON={users:'<circle cx="9" cy="8" r="3.2"/><path d="M3 20c0-3.3 2.7-5.5 6-5.5s6 2.2 6 5.5"/><path d="M16 4.5a3 3 0 0 1 0 6M18 14.8c1.9.7 3 2.5 3 5.2"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',dashboard:'<path d="M3 13h8V3H3zm10 8h8V11h-8zM3 21h8v-6H3zm10-18v6h8V3z"/>',projects:'<path d="M3 11 12 4l9 7v9H3z"/><path d="M9 20v-6h6v6"/>',products:'<path d="M4 10h16v8H4zM6 18v3M18 18v3M6 10V6h12v4"/>',categories:'<path d="M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z"/>',settings:'<path d="M3 21h18M5 21V8l7-5 7 5v13M9 21v-6h6v6"/>',testimonials:'<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>',orders:'<path d="M3 4h2l2.4 11.2a2 2 0 0 0 2 1.6h7.7a2 2 0 0 0 2-1.5L21 8H6.2"/>',publishing:'<path d="M12 3v12M7 8l5-5 5 5M5 15v4h14v-4"/>',documents:'<path d="M7 3h7l5 5v13H7z"/><path d="M14 3v5h5M10 13h6M10 17h6"/>',rates:'<path d="M4 6h16M4 12h16M4 18h10"/>',letterhead:'<path d="M5 3h14v18H5z"/><path d="M8 7h8M8 11h5"/>',account:'<rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>'};
const svg=k=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+ICON[k]+'</svg>';
const PAGES={users:{t:'Users & roles',s:'Team members, roles and what each person can do'},dashboard:{t:'Dashboard',s:'Your business at a glance'},mail:{t:'Mail',s:'All your business mailboxes in one place'},documents:{t:'Documents',s:'Quotations, agreements, bills and invoices'},rates:{t:'Rate list',s:'Your standard items and rates for quick quotations'},letterhead:{t:'Letterhead',s:'Name, intro, contact and payment details printed on every document'},projects:{t:'Our work',s:'Project sites shown in the Our work section',file:'projects'},products:{t:'Products',s:'Everything for sale in the shop',file:'products'},categories:{t:'Categories',s:'Rooms and furniture types used to group products',file:'categories'},settings:{t:'Business details',s:'Name, contact, locations, services and homepage text',file:'settings'},testimonials:{t:'Reviews',s:'Real customer reviews shown on the homepage',file:'testimonials'},orders:{t:'Orders & enquiries',s:'Orders arrive on WhatsApp and email'},publishing:{t:'Publishing',s:'Connect GitHub so changes go live instantly'},account:{t:'My account',s:'Your password and two-step sign-in'}};

/* ── GitHub ── */
function gh(){if(SERVER())return{...ghDefaults(),token:'@server'};try{return JSON.parse(localStorage.getItem(GHK)||'null')}catch(e){return null}}
function ghDefaults(){const h=location.hostname,p=h.endsWith('.github.io');return{owner:p?h.split('.')[0]:'AshishVDeveloper',repo:p&&location.pathname.split('/').filter(Boolean)[0]||'carpenter',branch:'main'}}
async function ghApi(cfg,path,opt={}){if(cfg.token==='@server')return srvGh(path,opt);const r=await fetch('https://api.github.com/repos/'+cfg.owner+'/'+cfg.repo+path,{...opt,headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+cfg.token,'X-GitHub-Api-Version':'2022-11-28',...(opt.headers||{})}});const j=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(j.message||'GitHub error '+r.status);e.status=r.status;throw e}return j}
const b64=s=>{const b=new TextEncoder().encode(s);let o='';for(let i=0;i<b.length;i+=0x8000)o+=String.fromCharCode(...b.subarray(i,i+0x8000));return btoa(o)};
async function ghPutRaw(cfg,path,base64,msg){let sha;try{sha=(await ghApi(cfg,'/contents/'+path+'?ref='+encodeURIComponent(cfg.branch))).sha}catch(e){if(e.status!==404)throw e}
  return ghApi(cfg,'/contents/'+path,{method:'PUT',body:JSON.stringify({message:msg,content:base64,branch:cfg.branch,...(sha?{sha}:{})})})}
const ghPut=(cfg,file,data,msg)=>ghPutRaw(cfg,'data/'+file,b64(JSON.stringify(data,null,2)+'\n'),msg);
async function ghCheck(cfg){const r=await ghApi(cfg,'');if(!r.permissions||!r.permissions.push)throw new Error('This token can read the repository but can\'t change it. Give it "Contents: Read and write" access.');return r}
function errText(e){if(e.code==='session')return'Your sign-in expired. Sign out and sign in again.';if(e.code&&e.status!==404&&e.status!==409&&e.status!==401)return e.message;if(e.status===401)return'GitHub rejected the token. It may have expired — create a new one in Publishing.';if(e.status===404)return'Repository not found, or the token has no access to it. Check Publishing.';if(e.status===409)return'The file changed on GitHub at the same time. Publish again.';return e.message||'Something went wrong.'}
function download(file,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}));a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
async function publish(key,btn){
  const file=key==='auth'?'auth.json':FILES[key],data=key==='auth'?AUTH:DB[key],cfg=gh();
  if(!cfg||!cfg.token){download(file,data);markClean(key);toast('Downloaded '+file+'. Upload it to the data folder on GitHub, or connect GitHub in Publishing to skip this.');return true}
  const label=btn&&btn.innerHTML;if(btn){btn.disabled=true;btn.innerHTML='<span class="spin"></span>Publishing…'}
  try{await ghPut(cfg,file,data,'Update '+file+' from store admin');markClean(key);toast('Published. The shop updates in about a minute.');return true}
  catch(e){toast(errText(e),true);return false}finally{if(btn){btn.disabled=false;btn.innerHTML=label}}}
async function publishAll(){const b=$('pubAll');for(const k of [...DIRTY]){if(!await publish(k,b))return}}
function markDirty(k){DIRTY.add(k);chrome()}
function markClean(k){if(k==='auth')return;DIRTY.delete(k);ORIG[k]=JSON.stringify(DB[k]);chrome()}
window.addEventListener('beforeunload',e=>{if(DIRTY.size){e.preventDefault();e.returnValue=''}});

/* photo upload: resize in the browser, then commit to images/products/ */
function resize(file,max=1400){return new Promise((res,rej)=>{const img=new Image();img.onload=()=>{const s=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*s);c.height=Math.round(img.height*s);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const w=c.toDataURL('image/webp',.8),ok=w.startsWith('data:image/webp');res({b64:(ok?w:c.toDataURL('image/jpeg',.82)).split(',')[1],ext:ok?'webp':'jpg'});URL.revokeObjectURL(img.src)};img.onerror=()=>rej(new Error('That file isn\'t an image the browser can read.'));img.src=URL.createObjectURL(file)})}
async function uploadPhotos(files,nameHint){
  const cfg=gh(); if(!cfg||!cfg.token){toast('Connect GitHub in Publishing to upload photos, or paste an image link instead.',true);return[]}
  const out=[];
  for(const f of files){try{const r=await resize(f),path='images/'+(PAGE==='projects'?'work':'products')+'/'+slugify(nameHint)+'-'+Date.now().toString(36)+'.'+r.ext;
    await ghPutRaw(cfg,path,r.b64,'Add photo '+path);
    if(r.ext==='webp'&&PAGE!=='projects')for(const[w,sx]of[[600,'-sm'],[400,'-xs']]){const v=await resize(f,w);if(v.ext==='webp')await ghPutRaw(cfg,path.replace(/\.webp$/,sx+'.webp'),v.b64,'Add photo '+sx)}
    out.push(path)}catch(e){toast(e.status?errText(e):e.message,true)}}
  return out}

/* ── auth ── */
async function loadAuth(){AUTH=await fetchJSON('auth.json')}
const PBKDF2_ITER=600000;
async function pbkdf2Hex(pass,salt,iter){const k=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveBits']);const b=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:iter,hash:'SHA-256'},k,256);return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function checkPass(email,pass){if(!AUTH||email.trim().toLowerCase()!==String(AUTH.email).toLowerCase())return false;const e=email.trim().toLowerCase();
  if(AUTH.kdf==='pbkdf2')return await pbkdf2Hex(e+'|'+pass,AUTH.salt,AUTH.iter)===AUTH.hash;
  return await sha256(AUTH.salt+'|'+e+'|'+pass)===AUTH.password_sha256}
async function newAuth(pass){const salt=randHex(),e=String(AUTH.email).toLowerCase();return{email:AUTH.email,kdf:'pbkdf2',iter:PBKDF2_ITER,salt,hash:await pbkdf2Hex(e+'|'+pass,salt,PBKDF2_ITER)}}
const LOCK='carpenter_login_lock';
function lockState(){try{return JSON.parse(localStorage.getItem(LOCK)||'{}')}catch(e){return{}}}
function lockWait(){const l=lockState();return Math.max(0,Math.ceil(((l.until||0)-Date.now())/1000))}
function lockFail(){const l=lockState();l.n=(l.n||0)+1;if(l.n>=5)l.until=Date.now()+Math.min(900,30*2**(l.n-5))*1000;localStorage.setItem(LOCK,JSON.stringify(l))}
async function doLogin(e){e.preventDefault();$('lErr').hidden=true;
  const w=lockWait();if(w){$('lErr').textContent='Too many wrong tries. Wait '+(w>90?Math.ceil(w/60)+' minutes':w+' seconds')+' and try again.';$('lErr').hidden=false;return}
  if(SERVER())return srvLogin(e);
  if(AUTH&&AUTH.mode==='server'){$('lErr').textContent='Can\'t reach the sign-in server. Check your internet and try again in a minute.';$('lErr').hidden=false;return}
  $('lBtn').disabled=true;
  try{if(!AUTH)await loadAuth();if(await checkPass($('lEmail').value,$('lPass').value)){const pw=$('lPass').value;try{await vaultOpen(pw)}catch(er){if(!er.locked)throw er;if(!window.confirm('Your saved documents were locked with an older password and can\'t be opened. Start a new, empty document store? (You can restore a backup file afterwards.)')){$('lBtn').disabled=false;return}await vaultFresh(pw)}localStorage.removeItem(LOCK);
    if(AUTH.kdf!=='pbkdf2'&&gh()&&gh().token){try{const up=await newAuth(pw);await ghPut({...ghDefaults(),...gh()},'auth.json',up,'Upgrade admin password protection')}catch(er){}}
    sessionStorage.setItem(SESS,JSON.stringify({email:AUTH.email,t:Date.now()}));location.replace('/admin/'+location.hash);return}else{lockFail();const w2=lockWait();$('lErr').textContent=w2?'Too many wrong tries. Wait '+w2+' seconds and try again.':'Email or password is incorrect.';$('lErr').hidden=false}}
  catch(err){$('lErr').textContent='Couldn\'t load the login settings. Refresh and try again.';$('lErr').hidden=false}$('lBtn').disabled=false}
function showReset(on){$('loginForm').hidden=on;$('resetForm').hidden=!on;if(on&&SERVER())srvResetForm()}
async function doReset(e){e.preventDefault();$('rErr').hidden=$('rOk').hidden=true;if($('rNew').value!==$('rConf').value){$('rErr').textContent='The two passwords don\'t match.';$('rErr').hidden=false;return}
  if(SERVER())return srvReset();$('rBtn').disabled=true;try{if(!AUTH)await loadAuth();const cfg={...ghDefaults(),...(gh()||{}),token:$('rToken').value.trim()};await ghCheck(cfg);AUTH=await newAuth($('rNew').value);await ghPut(cfg,'auth.json',AUTH,'Reset admin password');$('rOk').textContent='Password changed. It works in about a minute.';$('rOk').hidden=false}
  catch(err){$('rErr').textContent=errText(err);$('rErr').hidden=false}$('rBtn').disabled=false}
function logout(){if(DIRTY.size&&!window.confirm('You have unpublished changes. Sign out anyway?'))return;DIRTY.clear();if(SERVER()&&srvSess())api('/logout',{}).catch(()=>{});setTimeout(()=>{sessionStorage.removeItem(SRVK);sessionStorage.removeItem(SESS);vaultForget();location.replace('/admin/login/')},150)}

/* ── boot & routing ── */
async function openApp(){
  try{const ks=Object.keys(FILES),vs=await Promise.all(ks.map(k=>fetchJSON(FILES[k]).catch(()=>(k==='testimonials'||k==='projects')?[]:Promise.reject(k))));ks.forEach((k,i)=>{DB[k]=vs[i];ORIG[k]=JSON.stringify(vs[i])})}
  catch(e){showLoadError();return}
  byOrder(DB.products);byOrder(DB.categories);byOrder(DB.projects);
  document.documentElement.classList.remove('booting');$('who').textContent=(ME.name&&ME.name!=='Owner'?ME.name+' · ':'')+ME.email+' · '+ME.roleName;$('who').title=$('who').textContent;
  new MutationObserver(applyPerms).observe($('content'),{childList:true,subtree:true});if(ME.mustChange&&!/^#account/.test(location.hash))location.hash='account';route()}
document.addEventListener('click',e=>{const a=e.target.closest&&e.target.closest('a[href^="#"]');if(!a||e.defaultPrevented||e.ctrlKey||e.metaKey||e.shiftKey)return;e.preventDefault();const h=a.getAttribute('href');if(location.hash!==h)location.hash=h;else route()});
window.addEventListener('hashchange',route);
const NAVG=[['','dashboard'],['Documents','documents','rates','letterhead'],['Business','settings','projects','testimonials'],['Furniture shop','products','categories'],['Customers','orders','mail'],['Settings','users','publishing','account']];
function route(){if(!$('app')||document.documentElement.classList.contains('booting'))return;let[p,arg]=(location.hash.slice(1)||'dashboard').split('/');PAGE=PAGES[p]?p:'dashboard';$('sb').classList.remove('open');
  if(!canView(PAGE)){const f=NAVG.flatMap(g=>g.slice(1)).find(canView);if(!location.hash||location.hash==='#dashboard'){PAGE=f;arg=undefined}else{PAGE=f;$('pTitle').textContent='No access';$('pSub').textContent='';C('<div class="card" style="max-width:560px"><h2>You don\'t have access to this page</h2><p>Your role is <b>'+esc(ME.roleName)+'</b>. Ask the owner if you need it.</p><div class="bar" style="justify-content:flex-start"><a class="btn pri" href="#'+f+'">Go to '+esc(PAGES[f].t)+'</a></div></div>');chrome();return}}
  $('pTitle').textContent=PAGES[PAGE].t;$('pSub').textContent=PAGES[PAGE].s;
  let ro={settings:!can('settings','edit'),letterhead:!can('letterhead','edit'),rates:!can('rates','edit'),categories:!can('categories','edit')&&!can('categories','add'),publishing:!can('publishing','edit')}[PAGE]||false;
  if(arg&&['products','projects','testimonials'].includes(PAGE))ro=!can(PAGE,arg==='new'?'add':'edit');
  if(arg&&PAGE==='documents')ro=!can('documents',/^new/.test(arg)?'add':'edit');
  if(ro)$('content').dataset.ro='1';else delete $('content').dataset.ro;
  if(['documents','rates','letterhead'].includes(PAGE)&&window.vaultReady&&!vaultReady()){C('<div class="card" style="max-width:600px"><h2>Documents are locked</h2><p>'+(ME.owner?'Sign out and sign in again to open your documents.':'The owner needs to sign in once so documents move to the team key. After that they open here for you.')+'</p></div>');chrome();return}
  ({users:()=>pgUsers(arg),mail:()=>pgMail(arg),dashboard:pgDash,documents:()=>arg?docRoute(arg):pgDocs(),rates:pgRates,letterhead:pgLetterhead,products:()=>arg?pgProduct(arg):pgProducts(),projects:()=>arg?pgProject(arg):pgProjects(),categories:pgCats,settings:pgSettings,testimonials:()=>arg?pgReview(arg):pgReviews(),orders:pgOrders,publishing:pgPublishing,account:pgAccount})[PAGE]();
  if(ro)$('content').insertAdjacentHTML('afterbegin','<div class="msg info">View only. Your role can\'t change this. Ask the owner if you need to.</div>');applyPerms();chrome();window.scrollTo(0,0)}
function chrome(){const cnt={documents:window.vaultCount?vaultCount():'',projects:DB.projects?.length,products:DB.products?.length,categories:DB.categories?.length,testimonials:DB.testimonials?.length||'',orders:orders().length||''};
  const G=NAVG.map(g=>[g[0],...g.slice(1).filter(canView)]).filter(g=>g.length>1);
  $('nav').innerHTML=G.map(g=>(g[0]?'<div class="grp">'+g[0]+'</div>':'')+g.slice(1).map(k=>'<a href="#'+k+'" class="'+(k===PAGE?'on':'')+'"'+(k===PAGE?' aria-current="page"':'')+'>'+svg(k)+PAGES[k].t+(DIRTY.has(k)?'<span class="dirty" title="Unpublished changes"></span>':'')+(cnt[k]?'<span class="n">'+cnt[k]+'</span>':'')+'</a>').join('')).join('');
  const c=gh();$('conn').className='conn'+(c&&c.token?' ok':'');$('conn').querySelector('span').textContent=c&&c.token?'Publishing to GitHub':'Not connected';
  $('pubAll').hidden=!DIRTY.size;$('pubAll').textContent=DIRTY.size>1?'Publish all changes ('+DIRTY.size+')':'Publish changes'}
if($('burger'))$('burger').onclick=()=>$('sb').classList.toggle('open');
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('sb')){$('sb').classList.remove('open');if(!$('modal').hidden)$('mNo').click()}});
const C=h=>$('content').innerHTML=h;
/* ── pagination: every list shows Sr. No., rows per page and numbered pages; goes back to page 1 when the search or filter changes ── */
const PGS={};
function pageOf(key,arr,sig=''){const st=PGS[key]||(PGS[key]={p:1,n:(()=>{try{const v=localStorage.getItem('mi_pg_'+key);return v===null?10:+v}catch(e){return 10}})()});if(st.sig!==sig){st.sig=sig;st.p=1}
  const total=arr.length,n=st.n>0?st.n:Math.max(total,1),pages=Math.max(1,Math.ceil(total/n));st.p=Math.min(Math.max(1,st.p),pages);const from=(st.p-1)*n;
  return{key,rows:arr.slice(from,from+n),from,total,pages,p:st.p,n:st.n}}
function pagerHTML(pg,fn){if(!pg.total)return'';const P=pg.pages,c=pg.p,nums=[];for(let i=1;i<=P;i++){if(i===1||i===P||Math.abs(i-c)<=1)nums.push(i);else if(nums[nums.length-1]!=='…')nums.push('…')}
  const b=(p,l,cur,dis,aria)=>'<button type="button" class="pgb'+(cur?' on':'')+'"'+(dis?' disabled':'')+(cur?' aria-current="page"':'')+' aria-label="'+(aria||'Page '+p)+'" onclick="pgGo(\''+pg.key+'\','+p+',\''+fn+'\')">'+l+'</button>';
  return '<div class="pager"><span class="pginfo">'+(pg.from+1)+'–'+(pg.from+pg.rows.length)+' of '+pg.total+'</span>'+(P>1?'<div class="pgnav">'+b(c-1,'‹',0,c<=1,'Previous page')+nums.map(x=>x==='…'?'<span class="pgdots">…</span>':b(x,x,x===c)).join('')+b(c+1,'›',0,c>=P,'Next page')+'</div>':'<span></span>')+
    '<label class="pgsize">Rows <select class="keep" onchange="pgSize(\''+pg.key+'\',this.value,\''+fn+'\')">'+[10,25,50,100,0].map(v=>'<option value="'+v+'"'+(v===pg.n?' selected':'')+'>'+(v||'All')+'</option>').join('')+'</select></label></div>'}
function pgMount(el,pg,fn){if(!el)return;const host=el.closest('.tw')||el;let w=host.nextElementSibling;if(!w||!w.classList.contains('pgwrap')){w=document.createElement('div');w.className='pgwrap';host.after(w)}w.dataset.k=pg.key;w.innerHTML=pagerHTML(pg,fn)}
function pgGo(k,p,fn){PGS[k].p=p;window[fn]();const w=document.querySelector('.pgwrap[data-k="'+k+'"]'),c=w&&(w.closest('.card')||w);if(c&&c.getBoundingClientRect().top<0)c.scrollIntoView({block:'start'})}
function pgSize(k,n,fn){PGS[k].n=+n;PGS[k].p=1;try{localStorage.setItem('mi_pg_'+k,n)}catch(e){}window[fn]()}
const sr=(pg,j)=>'<td class="sr">'+(pg.from+j+1)+'</td>';

const saveBar=k=>!canWrite(k)?'':'<div class="bar">'+(DIRTY.has(k)?'<button class="btn" onclick="discard(\''+k+'\')">Discard changes</button>':'')+'<button class="btn pri" onclick="publish(\''+k+'\',this)">Publish '+PAGES[k].t.toLowerCase()+'</button></div>';
async function discard(k){if(!await confirmBox('Discard changes?','Your unpublished edits will be lost.','Discard'))return;DB[k]=JSON.parse(ORIG[k]);DIRTY.delete(k);route()}
function mv(k,i,d,redraw){const a=DB[k],j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renumber(a);markDirty(k);redraw()}
const catName=s=>(DB.categories.find(c=>c.slug===s)||{}).name||s||'—';

/* ── dashboard ── */
function pgDash(){const P=DB.products,c=gh(),S=DB.settings;
  C((c&&c.token?'':'<div class="msg info"><b>Connect GitHub first.</b> Then every Publish button updates the live shop, and you can upload product photos. <a href="#publishing">Set up publishing</a></div>')+
  (S.sample_data?'<div class="msg info"><b>Sample products are showing.</b> Replace them with your real furniture, photos and prices in <a href="#products">Products</a>, check your details in <a href="#settings">Shop details</a>, then untick "Sample data" there.</div>':'')+
  (DIRTY.size?'<div class="msg info">Unpublished changes in: '+[...DIRTY].map(k=>'<a href="#'+k+'">'+PAGES[k].t+'</a>').join(', ')+'.</div>':'')+
  '<div class="stats">'+[['projects',DB.projects.length,'Project sites'],['products',P.length,'Products'],['products',P.filter(p=>p.visible===false).length,'Hidden'],['categories',DB.categories.length,'Categories'],['testimonials',DB.testimonials.length,'Reviews'],['orders',orders().length,'Orders on this device']].map(s=>'<a href="#'+s[0]+'"><b>'+s[1]+'</b><span>'+s[2]+'</span></a>').join('')+'</div>'+
  '<div class="card"><h2>Quick actions</h2><div class="bar" style="justify-content:flex-start"><a class="btn pri" href="#documents/new-quotation">New quotation</a><a class="btn" href="#documents">Documents</a><a class="btn" data-perm="projects.add" href="#projects/new">Add a project site</a><a class="btn" data-perm="products.add" href="#products/new">Add a product</a><a class="btn" href="#settings">Edit business details</a><a class="btn" data-perm="testimonials.add" href="#testimonials/new">Add a review</a><a class="btn" href="/" target="_blank" rel="noopener">Open the website</a></div></div>')}

/* ── products ── */
let PQ='',PC='';
function pgProducts(){C('<div class="card"><h2>All products <a class="btn sm pri" data-perm="products.add" href="#products/new">Add product</a></h2><div class="tools"><input type="search" placeholder="Search products" aria-label="Search products" value="'+esc(PQ)+'" oninput="PQ=this.value;drawProducts()"/><select aria-label="Category" onchange="PC=this.value;drawProducts()"><option value="">All categories</option>'+DB.categories.map(c=>'<option value="'+esc(c.slug)+'"'+(PC===c.slug?' selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></div><div class="tw"><table><thead><tr><th class="sr">Sr.</th><th data-perm="products.edit">Order</th><th></th><th>Product</th><th>Estimate</th><th class="hide-m">Status</th><th><span hidden>Actions</span></th></tr></thead><tbody id="pRows"></tbody></table></div></div>'+saveBar('products'));drawProducts()}
function drawProducts(){const q=PQ.toLowerCase(),R=DB.products.map((p,i)=>[p,i]).filter(([p])=>(!PC||p.category===PC)&&(!q||(p.name+' '+p.material).toLowerCase().includes(q)));
  const pg=pageOf('products',R,q+'|'+PC);$('pRows').innerHTML=R.length?pg.rows.map(([p,i],j)=>'<tr>'+sr(pg,j)+'<td data-perm="products.edit"><div class="mv"><button aria-label="Move up" onclick="mv(\'products\','+i+',-1,drawProducts)">▲</button><button aria-label="Move down" onclick="mv(\'products\','+i+',1,drawProducts)">▼</button></div></td><td><img class="th" src="'+esc((p.images||[])[0]||'assets/logo.svg')+'" alt=""/></td><td><div class="t">'+esc(p.name)+'</div><div class="s">'+esc(catName(p.category))+'</div></td><td><b>'+money(p.price_min||p.price)+'</b><div class="s">to '+money(p.price_max||Math.round((p.price_min||p.price)*1.4))+'</div></td><td class="hide-m">'+(p.visible===false?'<span class="pill">Hidden</span> ':'')+(p.featured?'<span class="pill star">Featured</span> ':'')+(p.in_stock===false?'<span class="pill warn">Made to order</span>':'<span class="pill ok">In stock</span>')+'</td><td><div class="acts-cell"><a class="btn sm" href="#products/'+p.id+'">'+(can('products','edit')?'Edit':'View')+'</a><button class="btn sm danger" data-perm="products.delete" onclick="delProduct('+i+')">Delete</button></div></td></tr>').join(''):'<tr><td colspan="7" class="empty">No products match.</td></tr>';pgMount($('pRows'),pg,'drawProducts')}
async function delProduct(i){if(!await confirmBox('Delete '+DB.products[i].name+'?','It disappears from the shop when you publish.'))return;DB.products.splice(i,1);renumber(DB.products);markDirty('products');drawProducts()}
let IMGS=[];
function pgProduct(id){const isNew=id==='new',p=isNew?{name:'',category:(DB.categories[0]||{}).slug||'',price:'',price_min:'',price_max:'',material:'',size:'',finish:'',description:'',images:[],featured:false,customizable:true,in_stock:true,visible:true}:DB.products.find(x=>String(x.id)===id);
  if(!p){location.hash='products';return}$('pTitle').textContent=isNew?'Add product':'Edit product';IMGS=[...(p.images||[])];
  C('<form class="card" id="pf" onsubmit="saveProduct(event,\''+id+'\')"><h2>Photos</h2><div class="imgs" id="imgs"></div><div class="upl"><label class="btn sm" for="pFiles" style="margin:0">Upload photos</label><input id="pFiles" type="file" accept="image/*" multiple hidden/><span class="hint" style="margin:0">or</span><input id="pUrl" type="url" placeholder="Paste an image link" style="max-width:280px;padding:.4rem .6rem"/><button type="button" class="btn sm" onclick="addUrl()">Add link</button></div><p class="hint">The first photo is the main one. Photos are resized automatically.</p>'+
  '<h2 style="margin-top:1.4rem">Details</h2><div class="g2"><div class="field"><label for="p_name">Product name</label><input id="p_name" required value="'+esc(p.name)+'"/></div><div class="field"><label for="p_cat">Category</label><select id="p_cat">'+DB.categories.map(c=>'<option value="'+esc(c.slug)+'"'+(c.slug===p.category?' selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></div>'+
  '<div class="field"><label for="p_price">Estimated price from (₹)</label><input id="p_price" type="number" min="0" required value="'+esc(p.price_min||p.price)+'"/></div><div class="field"><label for="p_max">Estimated price up to (₹)</label><input id="p_max" type="number" min="0" required value="'+esc(p.price_max||'')+'"/><div class="hint">The website shows a range, e.g. ₹35,000 – ₹55,000. The final price is confirmed after measurement.</div></div>'+
  '<div class="field"><label for="p_mat">Material</label><input id="p_mat" value="'+esc(p.material)+'" placeholder="e.g. Sheesham wood"/></div><div class="field"><label for="p_size">Size</label><input id="p_size" value="'+esc(p.size)+'" placeholder="e.g. 200 × 85 × 82 cm"/></div>'+
  '<div class="field"><label for="p_fin">Finish / colour</label><input id="p_fin" value="'+esc(p.finish)+'" placeholder="e.g. Honey polish"/></div></div>'+
  '<div class="field"><label for="p_desc">Description</label><textarea id="p_desc" required>'+esc(p.description)+'</textarea></div>'+
  '<div class="g2"><div><div class="check"><input type="checkbox" id="p_feat"'+(p.featured?' checked':'')+'/><label for="p_feat">Featured on the homepage</label></div><div class="check"><input type="checkbox" id="p_cust"'+(p.customizable?' checked':'')+'/><label for="p_cust">Can be made in a custom size</label></div></div><div><div class="check"><input type="checkbox" id="p_stock"'+(p.in_stock!==false?' checked':'')+'/><label for="p_stock">Ready stock (untick for made to order)</label></div><div class="check"><input type="checkbox" id="p_vis"'+(p.visible!==false?' checked':'')+'/><label for="p_vis">Show in the shop</label></div></div></div>'+
  '<div class="bar"><a class="btn" href="#products">Cancel</a><button class="btn pri">'+(isNew?'Add product':'Save product')+'</button></div></form>');
  drawImgs();$('pFiles').onchange=async e=>{const fs=[...e.target.files];if(!fs.length)return;toast('Uploading '+fs.length+' photo'+(fs.length>1?'s':'')+'…');const paths=await uploadPhotos(fs,$('p_name').value||'product');IMGS.push(...paths);drawImgs();if(paths.length)toast('Photo uploaded. Save the product, then publish.');e.target.value=''}}
function drawImgs(){$('imgs').innerHTML=IMGS.map((s,i)=>'<figure><img src="'+esc(s)+'" alt=""/>'+(i===0?'<span>Main</span>':'<button type="button" class="mvl" title="Make main photo" aria-label="Make main photo" onclick="IMGS.unshift(IMGS.splice('+i+',1)[0]);drawImgs()">★</button>')+'<button type="button" aria-label="Remove photo" onclick="IMGS.splice('+i+',1);drawImgs()">✕</button></figure>').join('')||'<p class="hint">No photos yet.</p>'}
function addUrl(){const u=$('pUrl').value.trim();if(!/^(https?:\/\/|images\/)/.test(u)){toast('Paste a full image link starting with https://',true);return}IMGS.push(u);$('pUrl').value='';drawImgs()}
function saveProduct(e,id){e.preventDefault();const v=k=>$(k).value.trim();
  const d={name:v('p_name'),category:$('p_cat').value,price:+v('p_price')||0,price_min:+v('p_price')||0,price_max:Math.max(+v('p_max')||0,+v('p_price')||0),mrp:null,material:v('p_mat'),size:v('p_size'),finish:v('p_fin'),description:v('p_desc'),images:[...IMGS],featured:$('p_feat').checked,customizable:$('p_cust').checked,in_stock:$('p_stock').checked,visible:$('p_vis').checked};
  if(id==='new'){DB.products.unshift({id:nextId(DB.products),order:1,...d});renumber(DB.products)}else Object.assign(DB.products.find(x=>String(x.id)===id),d);
  markDirty('products');toast((id==='new'?'Product added':'Product saved')+'. Publish to show it in the shop.');location.hash='products'}

/* ── categories ── */
function pgCats(){C('<div class="card"><h2>Categories <button class="btn sm pri" data-perm="categories.add" onclick="addCat()">Add category</button></h2><p class="hint" style="margin:-.5rem 0 1rem">Categories with no products are hidden in the shop automatically.</p><div id="cRows"></div></div>'+saveBar('categories'));drawCats()}
function drawCats(){const pg=pageOf('categories',DB.categories.map((c,i)=>[c,i]));$('cRows').innerHTML='<div class="r cat rhead"><span>Sr.</span><span></span><span>Name</span><span>Products</span><span></span></div>'+pg.rows.map(([c,i],j)=>{const n=DB.products.filter(p=>p.category===c.slug).length;return '<div class="r cat"><span class="sr">'+(pg.from+j+1)+'</span><div class="mv" data-perm="categories.edit"><button aria-label="Move up" onclick="mv(\'categories\','+i+',-1,drawCats)">▲</button><button aria-label="Move down" onclick="mv(\'categories\','+i+',1,drawCats)">▼</button></div><input aria-label="Category name" value="'+esc(c.name)+'" oninput="DB.categories['+i+'].name=this.value;markDirty(\'categories\')"/><span class="hint" style="margin:0">'+n+' product'+(n===1?'':'s')+' · /'+esc(c.slug)+'</span><button class="btn sm danger" data-perm="categories.delete" onclick="delCat('+i+')">Delete</button></div>'}).join('');pgMount($('cRows'),pg,'drawCats')}
function addCat(){const name=prompt('Category name, e.g. Shoe racks');if(!name)return;let s=slugify(name);while(DB.categories.some(c=>c.slug===s))s+='-2';DB.categories.push({id:nextId(DB.categories),order:DB.categories.length+1,name:name.trim(),slug:s});markDirty('categories');drawCats()}
async function delCat(i){const c=DB.categories[i],n=DB.products.filter(p=>p.category===c.slug).length;if(n){toast('Move or delete the '+n+' product'+(n>1?'s':'')+' in '+c.name+' first.',true);return}if(!await confirmBox('Delete '+c.name+'?','It is removed from the shop when you publish.'))return;DB.categories.splice(i,1);renumber(DB.categories);markDirty('categories');drawCats()}

/* ── settings ── */
function pgSettings(){const S=DB.settings,f=(k,l,t='text',h='')=>'<div class="field"><label for="s_'+k+'">'+l+'</label><input id="s_'+k+'" type="'+t+'" data-k="'+k+'" value="'+esc(S[k]||'')+'"/>'+(h?'<div class="hint">'+h+'</div>':'')+'</div>',ta=(k,l,h='')=>'<div class="field"><label for="s_'+k+'">'+l+'</label><textarea id="s_'+k+'" data-k="'+k+'">'+esc(S[k]||'')+'</textarea>'+(h?'<div class="hint">'+h+'</div>':'')+'</div>';
  C('<div class="card"><h2>Business</h2><div class="g2">'+f('name','Business name')+f('short','Short name (top-left logo)')+'</div>'+f('tagline','Tagline')+f('top_note','Strip at the very top','text','e.g. Diwali sale — 10% off all beds')+'</div>'+
  '<div class="card"><h2>Homepage</h2>'+f('hero_title','Big headline')+ta('hero_text','Text under the headline')+ta('about','About the business','Shown on the About page and in the footer.')+'<div class="g3">'+f('years','Years in business','text','e.g. 10+')+f('warranty','Warranty line')+f('currency','Currency symbol')+'</div>'+ta('delivery_note','Delivery note')+'</div>'+
  '<div class="card"><h2>Services <button type="button" class="btn sm" onclick="addRow(\'services\')">Add service</button></h2><div id="svcRows"></div></div>'+
  '<div class="card"><h2>Founder & team <button type="button" class="btn sm" onclick="addTeam()">Add person</button></h2><div id="teamRows"></div><p class="hint">Shown on the homepage, About page and footer.</p></div>'+
  '<div class="card"><h2>Ways to hire you <button type="button" class="btn sm" onclick="addRow(\'work_modes\')">Add</button></h2><div id="modeRows"></div></div>'+
  '<div class="card"><h2>Locations <button type="button" class="btn sm" onclick="addLoc()">Add location</button></h2><div id="locRows"></div><p class="hint">The first location is shown as the main office.</p></div>'+
  '<div class="card"><h2>Contact</h2><div class="g2">'+f('whatsapp','WhatsApp number with country code','tel','Orders go here. e.g. 919004200401')+f('phone','Phone','tel')+f('email','Email','email','Order copies are emailed here.')+f('hours','Opening hours')+'</div>'+f('map','Google Maps link for the main office','url')+'</div>'+
  '<div class="card"><h2>Search engines</h2><div class="g2">'+f('google_verification','Google Search Console code','text','Paste only the content="…" value from the HTML tag method.')+f('bing_verification','Bing Webmaster code','text','Optional.')+f('ga_id','Google Analytics ID','text','Optional. Looks like G-XXXXXXXXXX (Google Analytics → Admin → Data streams). Counts visits; the Privacy Policy mentions it automatically.')+'</div></div>'+
  '<div class="card"><div class="check" style="margin:0"><input type="checkbox" id="s_sample"'+(S.sample_data?' checked':'')+'/><label for="s_sample">Sample data — show a reminder in the admin until real products are added</label></div></div>'+saveBar('settings'));
  $('content').querySelectorAll('[data-k]').forEach(el=>el.oninput=()=>{S[el.dataset.k]=el.value;markDirty('settings')});$('s_sample').onchange=e=>{S.sample_data=e.target.checked;markDirty('settings')};drawLists()}
function drawLists(){const S=DB.settings;S.services=S.services||[];S.work_modes=S.work_modes||[];S.locations=S.locations||[];
  const pair=(key,i,o)=>'<div class="r" style="grid-template-columns:1fr 2fr auto"><input aria-label="Title" value="'+esc(o.title)+'" oninput="DB.settings.'+key+'['+i+'].title=this.value;markDirty(\'settings\')"/><input aria-label="Description" value="'+esc(o.desc)+'" oninput="DB.settings.'+key+'['+i+'].desc=this.value;markDirty(\'settings\')"/><button type="button" class="btn sm danger" onclick="DB.settings.'+key+'.splice('+i+',1);markDirty(\'settings\');drawLists()">Remove</button></div>';
  $('svcRows').innerHTML=S.services.map((o,i)=>pair('services',i,o)+'<div class="field" style="margin:-.3rem 0 1.2rem"><label for="se'+i+'" class="hint" style="margin:0 0 .2rem">Estimated costs for '+esc(o.title||'this service')+' — one per line: Work | Price range</label><textarea id="se'+i+'" style="min-height:70px" oninput="DB.settings.services['+i+'].est=this.value.split(\'\\n\').map(l=>l.split(\'|\')).filter(a=>a[0].trim()).map(a=>({item:a[0].trim(),range:(a[1]||\'\').trim()}));markDirty(\'settings\')">'+esc((o.est||[]).map(e=>e.item+' | '+e.range).join('\n'))+'</textarea></div>').join('')||'<p class="hint">No services yet.</p>';
  S.team=S.team||[];$('teamRows').innerHTML=S.team.map((t,i)=>'<div class="r" style="grid-template-columns:1fr 1fr auto"><input aria-label="Name" placeholder="Name" value="'+esc(t.name)+'" oninput="DB.settings.team['+i+'].name=this.value;markDirty(\'settings\')"/><input aria-label="Role" placeholder="Role, e.g. Founder" value="'+esc(t.role)+'" oninput="DB.settings.team['+i+'].role=this.value;markDirty(\'settings\')"/><button type="button" class="btn sm danger" onclick="DB.settings.team.splice('+i+',1);markDirty(\'settings\');drawLists()">Remove</button></div><div class="field" style="margin:-.3rem 0 1rem"><textarea aria-label="About '+esc(t.name)+'" placeholder="One or two lines about this person" style="min-height:60px" oninput="DB.settings.team['+i+'].bio=this.value;markDirty(\'settings\')">'+esc(t.bio||'')+'</textarea></div>').join('')||'<p class="hint">No people yet.</p>';
  $('modeRows').innerHTML=S.work_modes.map((o,i)=>pair('work_modes',i,o)).join('')||'<p class="hint">None yet.</p>';
  $('locRows').innerHTML=S.locations.map((l,i)=>'<div class="r" style="grid-template-columns:1fr auto"><input aria-label="Location" value="'+esc(l)+'" oninput="DB.settings.locations['+i+']=this.value;DB.settings.address=DB.settings.locations[0]||\'\';markDirty(\'settings\')"/><button type="button" class="btn sm danger" onclick="DB.settings.locations.splice('+i+',1);markDirty(\'settings\');drawLists()">Remove</button></div>').join('')||'<p class="hint">No locations yet.</p>'}
function addTeam(){DB.settings.team.push({name:'',role:'',bio:''});markDirty('settings');drawLists()}
function addRow(k){DB.settings[k].push({title:'',desc:''});markDirty('settings');drawLists()}
function addLoc(){DB.settings.locations.push('');markDirty('settings');drawLists();const r=$('locRows').lastElementChild.querySelector('input');r&&r.focus()}

/* ── our work (project sites) ── */
function pgProjects(){C('<div class="card"><h2>Project sites <a class="btn sm pri" data-perm="projects.add" href="#projects/new">Add project</a></h2><div class="tw"><table><thead><tr><th class="sr">Sr.</th><th data-perm="projects.edit">Order</th><th></th><th>Project</th><th><span hidden>Actions</span></th></tr></thead><tbody id="wRows"></tbody></table></div></div>'+saveBar('projects'));drawProjects()}
function drawProjects(){const pg=pageOf('projects',DB.projects.map((w,i)=>[w,i]));$('wRows').innerHTML=pg.rows.map(([w,i],j)=>'<tr>'+sr(pg,j)+'<td style="width:40px" data-perm="projects.edit"><div class="mv"><button aria-label="Move up" onclick="mv(\'projects\','+i+',-1,drawProjects)">▲</button><button aria-label="Move down" onclick="mv(\'projects\','+i+',1,drawProjects)">▼</button></div></td><td style="width:80px"><img class="th" src="'+esc((w.images||[])[0]||'assets/logo.svg')+'" alt=""/></td><td><div class="t">'+esc(w.title)+'</div><div class="s">'+esc(w.area)+' · '+esc(w.type)+' · '+((w.images||[]).length)+' photo'+((w.images||[]).length===1?'':'s')+'</div></td><td><div class="acts-cell"><a class="btn sm" href="#projects/'+w.id+'">'+(can('projects','edit')?'Edit':'View')+'</a><button class="btn sm danger" data-perm="projects.delete" onclick="delProject('+i+')">Delete</button></div></td></tr>').join('')||'<tr><td colspan="5" class="empty">No projects yet.</td></tr>';pgMount($('wRows'),pg,'drawProjects')}
async function delProject(i){if(!await confirmBox('Delete '+DB.projects[i].title+'?','It is removed from Our work when you publish.'))return;DB.projects.splice(i,1);renumber(DB.projects);markDirty('projects');drawProjects()}
function pgProject(id){const isNew=id==='new',w=isNew?{title:'',area:'',type:'Home interiors',description:'',images:[]}:DB.projects.find(x=>String(x.id)===id);if(!w){location.hash='projects';return}
  $('pTitle').textContent=isNew?'Add project site':'Edit project site';IMGS=[...(w.images||[])];
  C('<form class="card" onsubmit="saveProject(event,\''+id+'\')"><h2>Photos</h2><div class="imgs" id="imgs"></div><div class="upl"><label class="btn sm" for="pFiles" style="margin:0">Upload photos</label><input id="pFiles" type="file" accept="image/*" multiple hidden/><span class="hint" style="margin:0">or</span><input id="pUrl" type="url" placeholder="Paste an image link" style="max-width:280px;padding:.4rem .6rem"/><button type="button" class="btn sm" onclick="addUrl()">Add link</button></div><p class="hint">Before-and-after and finished-site photos work best.</p>'+
  '<h2 style="margin-top:1.4rem">Details</h2><div class="g3"><div class="field"><label for="w_title">Project / building</label><input id="w_title" required value="'+esc(w.title)+'" placeholder="e.g. Dreams building A1"/></div><div class="field"><label for="w_area">Area</label><input id="w_area" value="'+esc(w.area)+'" placeholder="e.g. Bhandup, Mumbai"/></div><div class="field"><label for="w_type">Type</label><input id="w_type" list="wtypes" value="'+esc(w.type)+'"/><datalist id="wtypes"><option value="Home interiors"><option value="Office"><option value="Shop / showroom"><option value="Mall"><option value="Commercial"><option value="Homes & shops"></datalist></div></div>'+
  '<div class="field"><label for="w_desc">What you did</label><textarea id="w_desc">'+esc(w.description)+'</textarea></div><div class="bar"><a class="btn" href="#projects">Cancel</a><button class="btn pri">'+(isNew?'Add project':'Save project')+'</button></div></form>');
  drawImgs();$('pFiles').onchange=async e=>{const fs=[...e.target.files];if(!fs.length)return;toast('Uploading '+fs.length+' photo'+(fs.length>1?'s':'')+'…');const paths=await uploadPhotos(fs,$('w_title').value||'site');IMGS.push(...paths);drawImgs();if(paths.length)toast('Photo uploaded. Save the project, then publish.');e.target.value=''}}
function saveProject(e,id){e.preventDefault();const d={title:$('w_title').value.trim(),area:$('w_area').value.trim(),type:$('w_type').value.trim(),description:$('w_desc').value.trim(),images:[...IMGS]};
  if(id==='new'){DB.projects.unshift({id:nextId(DB.projects),order:1,...d});renumber(DB.projects)}else Object.assign(DB.projects.find(x=>String(x.id)===id),d);markDirty('projects');toast('Project saved. Publish to show it.');location.hash='projects'}

/* ── reviews ── */
function pgReviews(){C('<div class="msg info">Only add reviews real customers gave you — with their permission to show their name.</div><div class="card"><h2>Reviews <a class="btn sm pri" data-perm="testimonials.add" href="#testimonials/new">Add review</a></h2><div class="tw"><table><thead><tr><th class="sr">Sr.</th><th>Review</th><th><span hidden>Actions</span></th></tr></thead><tbody id="tRows"></tbody></table></div></div>'+saveBar('testimonials'));drawReviews()}
function drawReviews(){const pg=pageOf('testimonials',DB.testimonials.map((r,i)=>[r,i]));$('tRows').innerHTML=pg.rows.map(([r,i],j)=>'<tr>'+sr(pg,j)+'<td><div class="t">'+esc(r.name)+' <span class="pill star">'+'★'.repeat(r.rating||5)+'</span></div><div class="s">'+esc(r.text)+'</div></td><td><div class="acts-cell"><a class="btn sm" href="#testimonials/'+i+'">'+(can('testimonials','edit')?'Edit':'View')+'</a><button class="btn sm danger" data-perm="testimonials.delete" onclick="delReview('+i+')">Delete</button></div></td></tr>').join('')||'<tr><td colspan="3" class="empty">No reviews yet. The homepage hides this section until you add one.</td></tr>';pgMount($('tRows'),pg,'drawReviews')}
async function delReview(i){if(!await confirmBox('Delete this review?','It is removed from the shop when you publish.'))return;DB.testimonials.splice(i,1);markDirty('testimonials');drawReviews()}
function pgReview(id){const isNew=id==='new',r=isNew?{name:'',place:'',rating:5,text:''}:DB.testimonials[+id];if(!r){location.hash='testimonials';return}
  $('pTitle').textContent=isNew?'Add review':'Edit review';
  C('<form class="card" onsubmit="saveReview(event,\''+id+'\')"><div class="g3"><div class="field"><label for="r_name">Customer name</label><input id="r_name" required value="'+esc(r.name)+'"/></div><div class="field"><label for="r_place">Area / what they bought</label><input id="r_place" value="'+esc(r.place)+'" placeholder="e.g. Airoli · King bed"/></div><div class="field"><label for="r_rate">Rating</label><select id="r_rate">'+[5,4,3,2,1].map(n=>'<option'+(n===(r.rating||5)?' selected':'')+'>'+n+'</option>').join('')+'</select></div></div><div class="field"><label for="r_text">What they said</label><textarea id="r_text" required>'+esc(r.text)+'</textarea></div><div class="bar"><a class="btn" href="#testimonials">Cancel</a><button class="btn pri">'+(isNew?'Add review':'Save review')+'</button></div></form>')}
function saveReview(e,id){e.preventDefault();const d={name:$('r_name').value.trim(),place:$('r_place').value.trim(),rating:+$('r_rate').value,text:$('r_text').value.trim()};if(id==='new')DB.testimonials.push(d);else DB.testimonials[+id]=d;markDirty('testimonials');toast('Review saved. Publish to show it.');location.hash='testimonials'}

/* ── orders ── */
function orders(){try{return JSON.parse(localStorage.getItem(ORD_KEY)||'[]')}catch(e){return[]}}
function pgOrders(){const A=orders(),S=DB.settings;
  C('<div class="msg info">Every order and enquiry opens on WhatsApp (<b>+'+esc(S.whatsapp)+'</b>) and a copy is emailed to <b>'+esc(S.email)+'</b>. The first time, FormSubmit sends you an <b>Activate</b> email — click it or the copies won\'t arrive.</div>'+
  '<div class="card"><h2>Placed from this browser ('+A.length+')'+(A.length?'<button class="btn sm danger" data-perm="orders.delete" onclick="clearOrders()">Clear</button>':'')+'</h2><p class="hint" style="margin:-.5rem 0 1rem">Useful for testing the checkout. Real customer orders are in your WhatsApp and email.</p>'+
  '<div id="oRows"></div></div>');drawOrders()}
function drawOrders(){const pg=pageOf('orders',orders());$('oRows').innerHTML=pg.total?pg.rows.map((o,j)=>'<div class="ord"><div class="t"><span class="srn">'+(pg.from+j+1)+'.</span> <b>'+(o.kind==='order'?'Order':o.kind==='custom'?'Quote request':'Enquiry')+'</b> — '+esc(o.name)+' · '+esc(o.phone||'')+' <span class="s">'+esc(o.date)+'</span></div><pre>'+(o.items?o.items.map(i=>esc(i.name)+' × '+i.q+' — '+money(i.price*i.q)).join('\n')+'\nTotal: '+money(o.total)+'\n'+esc(o.address||''):esc([o.work&&'Work: '+o.work,o.mode&&'Basis: '+o.mode,o.area&&'Site: '+o.area,o.size&&'Size: '+o.size,o.wood&&'Material: '+o.wood,o.budget&&'Budget: '+o.budget,o.details,o.message].filter(Boolean).join('\n')))+'</pre></div>').join(''):'<p class="empty">Nothing yet.</p>';pgMount($('oRows'),pg,'drawOrders')}
async function clearOrders(){if(!await confirmBox('Clear the list?','This only clears this browser.','Clear'))return;localStorage.removeItem(ORD_KEY);pgOrders();chrome()}

/* ── publishing ── */
function pgPublishing(){if(SERVER())return srvPublishing();const c={...ghDefaults(),...(gh()||{})};
  C('<div class="card"><h2>Connect GitHub</h2>'+(c.token?'<div class="msg ok">Connected. Publish buttons and photo uploads go to <b>'+esc(c.owner+'/'+c.repo)+'</b>.</div>':'')+
  '<ol style="margin:0 0 1.2rem 1.2rem;color:var(--muted)"><li>Open <a href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener">GitHub → New fine-grained token</a>.</li><li>Name it "Store admin", choose an expiry, and under <b>Repository access</b> pick <b>Only select repositories → '+esc(c.repo)+'</b>.</li><li>Under <b>Permissions → Contents</b> choose <b>Read and write</b>, generate the token and paste it below.</li></ol>'+
  '<form onsubmit="saveGh(event)"><div class="g3"><div class="field"><label for="g_owner">GitHub username</label><input id="g_owner" required value="'+esc(c.owner)+'"/></div><div class="field"><label for="g_repo">Repository</label><input id="g_repo" required value="'+esc(c.repo)+'"/></div><div class="field"><label for="g_branch">Branch</label><input id="g_branch" required value="'+esc(c.branch)+'"/></div></div>'+
  '<div class="field"><label for="g_token">Token</label><input id="g_token" type="password" autocomplete="off" placeholder="'+(c.token?'Saved — paste a new one to replace it':'github_pat_…')+'"/><div class="hint">Stored only in this browser. Sign out on shared computers.</div></div><div class="bar">'+(c.token?'<button type="button" class="btn danger" onclick="disconnectGh()">Disconnect</button>':'')+'<button class="btn pri" id="gBtn">'+(c.token?'Save and test':'Connect')+'</button></div></form></div>')}
async function saveGh(e){e.preventDefault();const old=gh()||{},cfg={owner:$('g_owner').value.trim(),repo:$('g_repo').value.trim(),branch:$('g_branch').value.trim(),token:$('g_token').value.trim()||old.token};if(!cfg.token){toast('Paste a token first.',true);return}
  $('gBtn').disabled=true;$('gBtn').textContent='Testing…';try{await ghCheck(cfg);localStorage.setItem(GHK,JSON.stringify(cfg));toast('GitHub connected.');pgPublishing();chrome()}catch(err){toast(errText(err),true);$('gBtn').disabled=false;$('gBtn').textContent='Connect'}}
async function disconnectGh(){if(!await confirmBox('Disconnect GitHub?','Publish buttons will download files instead.','Disconnect'))return;localStorage.removeItem(GHK);pgPublishing();chrome()}

/* ── account ── */
function pgAccount(){C('<form class="card" style="max-width:480px" onsubmit="changePw(event)"><h2>Change password</h2><div class="msg err" id="aErr" hidden></div>'+(ME&&ME.mustChange?'<div class="msg info">Welcome! Please choose your own password now.</div>':'')+'<p class="hint">Signed in as <b>'+esc(ME?ME.email:'')+'</b>'+(ME?' · '+esc(ME.roleName):'')+'</p><input type="text" autocomplete="username" value="'+esc(ME?ME.email:AUTH.email)+'" hidden/><div class="field"><label for="a_cur">Current password</label><input id="a_cur" type="password" autocomplete="current-password" required/></div><div class="field"><label for="a_new">New password</label><input id="a_new" type="password" autocomplete="new-password" minlength="8" required/><div class="hint">At least 8 characters.</div></div><div class="field"><label for="a_conf">Repeat new password</label><input id="a_conf" type="password" autocomplete="new-password" required/></div>'+(SERVER()?codeField('a_code','Code from your authenticator app'):'')+'<div class="bar"><button class="btn pri" id="aBtn">Change password</button></div></form>');srvCard()}
async function changePw(e){e.preventDefault();if(SERVER())return srvChangePw(e);const err=m=>{$('aErr').textContent=m;$('aErr').hidden=false};$('aErr').hidden=true;
  if(!await checkPass(AUTH.email,$('a_cur').value))return err('Current password is incorrect.');if($('a_new').value!==$('a_conf').value)return err('The two new passwords don\'t match.');
  const prev=AUTH,np=$('a_new').value;AUTH=await newAuth(np);if(await publish('auth',$('aBtn'))){await vaultRekey(np);e.target.reset();toast(gh()?'Password changed. It works in about a minute.':'Downloaded auth.json — upload it to the data folder to activate the new password.')}else AUTH=prev}

(async()=>{try{await Promise.all([loadAuth(),loadApi()])}catch(e){}let ok=false;try{const s=sessionStorage.getItem(SESS);if(s&&AUTH){if(SERVER()){if(srvSess()){try{ME=await api('/me');ok=true}catch(e){}}if(ok)await vaultResume().catch(()=>false)}else{ok=JSON.parse(s).email===AUTH.email&&await vaultResume();if(ok)ME=localME()}}}catch(e){}
  const onLogin=!!$('loginForm');if(onLogin&&/[?&]timeout=1/.test(location.search)){$('lErr').textContent='You were signed out after 30 minutes without activity.';$('lErr').hidden=false}
  if(onLogin){if(ok){location.replace('/admin/'+location.hash);return}document.documentElement.classList.remove('checking');if(!AUTH){$('lErr').textContent=navigator.onLine?'Couldn\'t reach the server. Refresh in a minute.':'You\'re offline. Connect to the internet to sign in.';$('lErr').hidden=false}$('lEmail').focus()}
  else{if(ok){openApp().then(()=>setTimeout(()=>mailBadge(),1500));idleWatch();srvSwitchAuth()}else{sessionStorage.removeItem(SESS);location.replace('/admin/login/'+location.hash)}}})();
function showLoadError(){document.documentElement.classList.remove('booting');$('pTitle').textContent='Connection problem';$('nav').innerHTML='';
  $('content').innerHTML='<div class="card" style="max-width:520px"><h2>Couldn\'t load your shop data</h2><p>'+(navigator.onLine?'GitHub didn\'t answer. Wait a minute and try again.':'You\'re offline. Check your mobile data or Wi-Fi.')+' Nothing was lost — your saved work is safe.</p><div class="bar" style="justify-content:flex-start"><button class="btn pri" onclick="location.reload()">Try again</button><a class="btn" href="/" target="_blank" rel="noopener">Open the website</a></div></div>'}
function idleWatch(){let last=Date.now();const bump=()=>last=Date.now();['pointerdown','keydown','scroll','touchstart'].forEach(ev=>addEventListener(ev,bump,{passive:true}));
  setInterval(()=>{if(Date.now()-last<30*60*1000)return;if(DIRTY.size){toast('You have unpublished changes. Publish them — you will be signed out soon for safety.',true);last=Date.now()-25*60*1000;return}
    sessionStorage.removeItem(SESS);sessionStorage.removeItem(SRVK);vaultForget();location.replace('/admin/login/?timeout=1')},60000)}
if('serviceWorker' in navigator)addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
